#pragma once
#ifdef HAVE_BUILD_CONFIG_H
  #include <build-config.h>
#endif

#include "Actions.hpp"

#include <tao/pegtl.hpp>

namespace usbguard
{
  namespace RuleParser
  {
    using namespace tao::pegtl;
    /*
     * Rule language keywords
     */
    struct str_allow : TAO_PEGTL_STRING("allow") {};

    struct str_block : TAO_PEGTL_STRING("block") {};

    struct str_reject : TAO_PEGTL_STRING("reject") {};

    struct str_match : TAO_PEGTL_STRING("match") {};

    struct str_device : TAO_PEGTL_STRING("device") {};

    struct str_name : TAO_PEGTL_STRING("name") {};

    struct str_hash : TAO_PEGTL_STRING("hash") {};

    struct str_parent_hash : TAO_PEGTL_STRING("parent-hash") {};

    struct str_via_port : TAO_PEGTL_STRING("via-port") {};

    struct str_with_interface : TAO_PEGTL_STRING("with-interface") {};

    struct str_with_connect_type : TAO_PEGTL_STRING("with-connect-type") {};

    struct str_serial : TAO_PEGTL_STRING("serial") {};

    struct str_if : TAO_PEGTL_STRING("if") {};

    struct str_id : TAO_PEGTL_STRING("id") {};

    struct str_label : TAO_PEGTL_STRING("label") {};

    struct str_all_of : TAO_PEGTL_STRING("all-of") {};

    struct str_one_of : TAO_PEGTL_STRING("one-of") {};

    struct str_none_of : TAO_PEGTL_STRING("none-of") {};

    struct str_equals : TAO_PEGTL_STRING("equals") {};

    struct str_equals_ordered : TAO_PEGTL_STRING("equals-ordered") {};

    struct str_match_all : TAO_PEGTL_STRING("match-all") {};

    /*
     * Generic rule attribute
     */
    struct multiset_operator : sor<str_all_of, str_one_of, str_none_of, str_equals_ordered, str_equals, str_match_all> {};

    template <class attribute_value_rule>
    struct attribute_value_multiset : seq<opt<multiset_operator, plus<ascii::blank>>, one<'{'>, star<ascii::blank>,
                                        list<attribute_value_rule, plus<ascii::blank>>, star<ascii::blank>, one<'}'>> {};

    template <class attribute_identifier, class attribute_value_rule>
    struct rule_attribute : seq<attribute_identifier, plus<ascii::blank>,
                              sor<attribute_value_multiset<attribute_value_rule>, attribute_value_rule>> {};

    /*
     * Bounded string value
     */
    struct escaped_single : one<'a', 'b', 'f', 'n', 'r', 't', 'v', '\\', '\'', '0', '\n'> {};

    struct escaped_decbyte : if_must<ascii::digit, rep_opt<2, ascii::digit>> {};

    struct escaped_hexbyte : if_must<one<'x'>, rep<2, ascii::xdigit>> {};

    template <char boundary_escape>
    struct character_escaped : if_must<one<'\\'>, sor<escaped_hexbyte, escaped_decbyte, escaped_single, one<boundary_escape>>> {
    };

    struct character_regular : not_one<'\r', '\n'> {};

    template <char boundary_escape> struct character : sor<character_escaped<boundary_escape>, character_regular> {};

    template <char boundary_start, char boundary_end = boundary_start>
    struct bounded_string : if_must<one<boundary_start>, until<one<boundary_end>, character<boundary_end>>> {};

    struct string_value : bounded_string<'"'> {};

    /*
     * Rule conditions
     */
    struct condition_argument : bounded_string<'(', ')'> {};

    struct condition_identifier : seq<ranges<'a', 'z', 'A', 'Z', '-'>, star<ranges<'a', 'z', 'A', 'Z', '0', '9', '-'>>> {};

    struct negation : one<'!'> {};

    struct condition : seq<opt<negation>, condition_identifier, opt<condition_argument>> {};

    /*
     * Device ID
     */
    struct hex4 : rep<4, ascii::xdigit> {};

    struct device_vid : sor<hex4, one<'*'>> {};
    struct device_pid : sor<hex4, one<'*'>> {};

    struct device_id_value : seq<device_vid, one<':'>, device_pid> {};

    struct device_id : device_id_value {};

    /*
     * USB interface notation
     */
    struct hex2 : rep<2, ascii::xdigit> {};

    struct hex2orAsterisk : sor<hex2, one<'*'>> {};

    struct interface_value : seq<hex2, one<':'>, hex2orAsterisk, one<':'>, hex2orAsterisk> {};

    /*
     * Device attributes
     */
    struct id_attribute : action<id_actions, rule_attribute<str_id, device_id_value>> {};

    struct name_attribute : action<name_actions, rule_attribute<str_name, string_value>> {};

    struct hash_attribute : action<hash_actions, rule_attribute<str_hash, string_value>> {};

    struct parent_hash_attribute : action<parent_hash_actions, rule_attribute<str_parent_hash, string_value>> {};

    struct serial_attribute : action<serial_actions, rule_attribute<str_serial, string_value>> {};

    struct with_connect_type_attribute
      : action<with_connect_type_actions, rule_attribute<str_with_connect_type, string_value>> {};

    struct via_port_attribute : action<via_port_actions, rule_attribute<str_via_port, string_value>> {};

    struct with_interface_attribute : action<with_interface_actions, rule_attribute<str_with_interface, interface_value>> {};

    struct condition_attribute : action<condition_actions, rule_attribute<str_if, condition>> {};

    struct label_attribute : action<label_actions, rule_attribute<str_label, string_value>> {};

    struct rule_attributes
      : sor<id_attribute, name_attribute, hash_attribute, parent_hash_attribute, serial_attribute, via_port_attribute,
          with_interface_attribute, with_connect_type_attribute, condition_attribute, label_attribute> {};

    /*
     * Rule target
     */
    struct target : sor<str_allow, str_block, str_reject, str_match, str_device> {};

    /*
     * Comment
     */
    struct comment : seq<star<ascii::blank>, if_must<one<'#'>, star<seq<not_at<eof>, any>>>> {};

    /*
     * Rule
     */
    struct rule : seq<target, opt<plus<ascii::blank>, device_id>,
                    opt<plus<ascii::blank>, list<rule_attributes, plus<ascii::blank>>>, opt<comment>, star<ascii::blank>> {};

    /*
     * Grammar entry point
     */
    struct rule_grammar : seq<star<ascii::blank>, opt<sor<comment, rule>>, must<eof>> {};
  } /* namespace RuleParser */
} /* namespace usbguard */

