  void FileRuleSet::load()
  {
    if (!isWritable()) {
      USBGUARD_LOG(Info) << "RuleSet is not writable";
      return;
    }

    load(_rulesPath);
  }

  void FileRuleSet::save()
  {
    save(_rulesPath);
  }

