int main(int argc, char* argv[])
{
  try {
    return usbguard::usbguard_cli(argc, argv);
  } catch (const usbguard::IPCException& ex) {
    std::cerr << "IPC ERROR: request id=" << ex.messageID() << ": " << ex.message() << std::endl;
