    std::cerr << "ERROR: " << ex.message() << std::endl;
  } catch (const std::exception& ex) {
    std::cerr << "EXCEPTION: " << ex.what() << std::endl;
  } catch (...) {
    std::cerr << "BUG: Unknown exception" << std::endl;
  }

  return EXIT_FAILURE;
}

