    int opt = 0;
    std::string label;

    while ((opt = getopt_long(argc, argv, options_short, options_long, nullptr)) != -1) {
      switch (opt) {
      case 'h':
        showHelp(std::cout);
        return EXIT_SUCCESS;

      case 'd':
        show_devices = true;
        break;

      case 'l':
        label = optarg;
        break;

      case '?':
        showHelp(std::cerr);

      default:
        return EXIT_FAILURE;
